def generate_signals(df: pd.DataFrame) -> pd.Series:
    close = df['close']
    ma_short = close.rolling(5).mean()
    ma_long = close.rolling(20).mean()

    signals = pd.Series(0.0, index=df.index)
    position = 0
    entry_price = 0.0

    for i in range(len(df)):
        if position == 0:
            if i >= 19 and ma_short.iloc[i] > ma_long.iloc[i]:
                signals.iloc[i] = 1.0
                position = 1
                entry_price = close.iloc[i]
        else:
            if close.iloc[i] < entry_price * 0.92 or ma_short.iloc[i] <= ma_long.iloc[i]:
                signals.iloc[i] = 0.0
                position = 0
                entry_price = 0.0
            else:
                signals.iloc[i] = 1.0
    return signals
